export function widgetIcon(name: keyof typeof icons, size = 16): SVGSVGElement {
  const source = new DOMParser().parseFromString(icons[name], 'image/svg+xml').documentElement;
  const svg = document.importNode(source, true) as unknown as SVGSVGElement;
  svg.setAttribute('aria-hidden', 'true'); svg.setAttribute('focusable', 'false');
  svg.setAttribute('width', String(size)); svg.setAttribute('height', String(size));
  svg.style.cssText = 'display:block;flex-shrink:0;';
  return svg;
}
